const sbBase = ($env.SUPABASE_URL || 'http://host.docker.internal:54321').replace(/\/$/, '');
const sbKey = $env.SUPABASE_SERVICE_ROLE_KEY || 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZS1kZW1vIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImV4cCI6MTk4MzgxMjk5Nn0.EGIM96RAZx35lJzdJsyH-qQwv8Hdp7fsn3W0YpN81IU';
const sbHeaders = { apikey: sbKey, Authorization: `Bearer ${sbKey}`, 'Content-Type': 'application/json' };

async function sb(method, path, body, prefer = 'return=minimal') {
  return await this.helpers.httpRequest({ method, url: `${sbBase}/rest/v1/${path}`, headers: { ...sbHeaders, Prefer: prefer }, body, json: true });
}

function actionValue(actions, type) {
  const a = (actions || []).find((x) => x.action_type === type);
  return a ? Math.round(parseFloat(a.value || 0)) : 0;
}

async function upsertInsight(row) {
  const existing = await sb.call(this, 'GET', `ad_insights_daily?clinic_id=eq.${row.clinic_id}&platform=eq.${row.platform}&campaign_id=eq.${encodeURIComponent(row.campaign_id)}&date=eq.${row.date}&select=id`);
  if (existing?.length) {
    await sb.call(this, 'PATCH', `ad_insights_daily?id=eq.${existing[0].id}`, row);
  } else {
    await sb.call(this, 'POST', 'ad_insights_daily', row);
  }
}

async function syncMeta(account, since, until) {
  const token = $env.META_ACCESS_TOKEN;
  if (!token) throw new Error('META_ACCESS_TOKEN eksik');
  let url = `https://graph.facebook.com/v21.0/${account.account_id}/insights?` + new URLSearchParams({
    level: 'campaign',
    time_increment: '1',
    time_range: JSON.stringify({ since, until }),
    fields: 'campaign_id,campaign_name,spend,impressions,clicks,ctr,cpc,actions,date_start',
    access_token: token,
    limit: '200',
  });
  let rows = 0;
  while (url) {
    const data = await this.helpers.httpRequest({ method: 'GET', url, json: true });
    for (const item of data.data || []) {
      const leads = actionValue(item.actions, 'lead') + actionValue(item.actions, 'onsite_conversion.lead_grouped');
      await upsertInsight.call(this, {
        clinic_id: account.clinic_id,
        platform: 'meta',
        account_id: account.account_id,
        campaign_id: item.campaign_id || 'unknown',
        campaign_name: item.campaign_name,
        date: item.date_start,
        currency: 'TRY',
        spend: parseFloat(item.spend || 0),
        impressions: parseInt(item.impressions || 0, 10),
        clicks: parseInt(item.clicks || 0, 10),
        leads,
        conversions: leads,
        cpc: parseFloat(item.cpc || 0) || null,
        ctr: parseFloat(item.ctr || 0) || null,
      });
      rows++;
    }
    url = data.paging?.next || null;
  }
  return rows;
}

async function syncGoogle(account, since, until) {
  const devToken = $env.GOOGLE_ADS_DEVELOPER_TOKEN;
  const accessToken = $env.GOOGLE_ADS_ACCESS_TOKEN;
  if (!devToken || !accessToken) throw new Error('GOOGLE_ADS_DEVELOPER_TOKEN / GOOGLE_ADS_ACCESS_TOKEN eksik');
  const customerId = account.account_id.replace(/-/g, '');
  const headers = { Authorization: `Bearer ${accessToken}`, 'developer-token': devToken };
  if ($env.GOOGLE_ADS_LOGIN_CUSTOMER_ID) headers['login-customer-id'] = $env.GOOGLE_ADS_LOGIN_CUSTOMER_ID.replace(/-/g, '');
  const query = `SELECT campaign.id, campaign.name, segments.date, metrics.cost_micros, metrics.impressions, metrics.clicks, metrics.conversions, metrics.ctr, metrics.average_cpc FROM campaign WHERE segments.date BETWEEN '${since}' AND '${until}'`;
  const data = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://googleads.googleapis.com/v18/customers/${customerId}/googleAds:searchStream`,
    headers,
    body: { query },
    json: true,
  });
  let rows = 0;
  const batches = Array.isArray(data) ? data : [data];
  for (const batch of batches) {
    for (const result of batch.results || []) {
      const costMicros = parseInt(result.metrics?.costMicros || 0, 10);
      const conv = Math.round(parseFloat(result.metrics?.conversions || 0));
      await upsertInsight.call(this, {
        clinic_id: account.clinic_id,
        platform: 'google',
        account_id: account.account_id,
        campaign_id: String(result.campaign?.id || 'unknown'),
        campaign_name: result.campaign?.name,
        date: result.segments?.date,
        currency: 'TRY',
        spend: costMicros / 1000000,
        impressions: parseInt(result.metrics?.impressions || 0, 10),
        clicks: parseInt(result.metrics?.clicks || 0, 10),
        leads: conv,
        conversions: conv,
        cpc: (parseInt(result.metrics?.averageCpc || 0, 10) / 1000000) || null,
        ctr: parseFloat(result.metrics?.ctr || 0) || null,
      });
      rows++;
    }
  }
  return rows;
}

const until = new Date(Date.now() - 86400000).toISOString().slice(0, 10);
const since = new Date(Date.now() - 7 * 86400000).toISOString().slice(0, 10);

const accounts = await sb.call(this, 'GET', 'ad_accounts?select=id,clinic_id,platform,account_id,account_name&status=eq.active&order=platform.asc');
const results = [];

for (const account of accounts) {
  try {
    const rows = account.platform === 'meta'
      ? await syncMeta.call(this, account, since, until)
      : await syncGoogle.call(this, account, since, until);
    await sb.call(this, 'PATCH', `ad_accounts?id=eq.${account.id}`, { last_synced_at: new Date().toISOString(), status: 'active' });
    results.push({ platform: account.platform, account: account.account_id, ok: true, rows });
  } catch (e) {
    if (/token/i.test(e.message)) {
      await sb.call(this, 'PATCH', `ad_accounts?id=eq.${account.id}`, { status: 'token_expired' }).catch(() => {});
    }
    results.push({ platform: account.platform, account: account.account_id, ok: false, error: e.message });
  }
}

return [{ json: { ok: true, at: new Date().toISOString(), since, until, results } }];
